// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount, uint256 initial) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 1e30);
        initial = bound(initial, 0, 1e30);

        if (initial > 0) {
            vm.deal(actor, initial);
            vm.prank(actor);
            c.addToBalance{value: initial}();
        }
        uint256 before = c.getBalance(actor);

        vm.deal(actor, amount + initial);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        assertTrue(c.getBalance(actor) == before + amount);
    }
}
